/**
 * Image lookup.
 *
 * `image-manifest.json` is generated by `scripts/fetch-images.mjs` and holds
 * the real intrinsic dimensions and an inline LQIP for every file under
 * `public/products` and `public/scene`. Importing it as JSON rather than using
 * static `import` of each file is deliberate: static imports only resolve in
 * modules the bundler can trace to a real path, and product art is rendered
 * from client components (the cart) as well as server ones.
 */

import manifest from "./image-manifest.json";

export type StoreImage = {
  src: string;
  width: number;
  height: number;
  alt: string;
  credit: string;
  blurDataURL: string;
};

export type ImageKey = keyof typeof manifest;

const images = manifest as Record<string, StoreImage>;

/**
 * Returns the manifest entry for `key`, or `undefined` if the asset has not
 * been fetched yet. Callers render a plain plate in that case rather than
 * throwing — a missing photo should not take a page down.
 */
export function getImage(key: string): StoreImage | undefined {
  return images[key];
}

export const allImages = images;
